// Contract between kits.ts (per-champion spell behaviour data) and fight.ts (teamfight AI). Owner: integrator.
// Keep it data-only so kits.gen.ts can be generated by a script.
import type { VfxKind } from "../data/types";

export type CcType =
  | "stun" | "root" | "knockup" | "knockback" | "pull" | "slow" | "charm" | "taunt" | "fear"
  | "sleep" | "suppress" | "silence" | "polymorph" | "blind" | "ground"
  /** walls the targets in (Jarvan IV R, Yorick W): they cannot walk out for `dur` */
  | "arena";

/** Saves an ally from death (all optional extras, added 2026-11-26 on the kits agent's request). */
export interface SaveKit {
  /** relocate = pulls the ally away (Kalista R, Thresh W lantern, Tahm Kench W on ally);
   *  invuln = cannot drop below 1 hp / untargetable (Taric R, Kindred R, Kayle R, Bard R stasis on ally);
   *  revive = brings the ally back once (Zilean R) */
  kind: "relocate" | "invuln" | "revive";
  dur: number;
  /** AoE saves (Kindred R, Taric R) cover allies within this radius of the target */
  radius?: number;
}

/** A buff on allies (not only the caster). */
export interface AllyBuffKit {
  kind: "as" | "ms" | "ad" | "dr" | "stasis";
  dur: number;
  /** radius around the caster (0 = single ally target) */
  radius: number;
}

/** What the AI uses a spell for, most important first. */
export type SpellUse =
  | "engage"    // starts a fight: hard CC / gap closer onto enemies
  | "poke"      // long-range damage before the fight
  | "burst"     // big damage on one target
  | "dps"       // damage in a prolonged fight
  | "cc"        // crowd control
  | "peel"      // protects own carry (CC / knockback on a diver)
  | "shield" | "heal" | "buff"
  | "escape"    // dash / blink away
  | "gapclose"  // dash / blink in
  | "zone"      // area denial that lingers
  | "execute"   // finishes low-hp targets
  | "waveclear" | "summon" | "stealth" | "global";

export interface SpellKit {
  key: "Q" | "W" | "E" | "R";
  slot: 0 | 1 | 2 | 3;
  uses: SpellUse[];
  /** who/what it is aimed at */
  target: "enemy" | "ally" | "self" | "area" | "direction";
  /** same vocabulary as champions.json `vfx` (the renderer draws by this) */
  shape: VfxKind;
  range: number;
  /** AoE radius in world units (0 = single target) */
  radius: number;
  width?: number;
  cc?: { type: CcType; dur: number };
  dash?: { len: number; to: "target" | "direction" | "ally"; overWalls: boolean };
  /** relative damage weight (comparable to SpellData.power; 0 = no damage) */
  dmg: number;
  /** relative shield / heal amount (0 = none) */
  support?: number;
  /** seconds from cast until it lands (cast time + travel); longer = easier to dodge */
  delay: number;
  /** can be dodged by moving */
  skillshot: boolean;
  /** base cooldown, seconds */
  cd: number;
  /** AI: wait until at least this many enemies can be hit (big AoE ults) */
  minTargets?: number;
  selfBuff?: { kind: "as" | "ms" | "ad" | "dr" | "untargetable" | "stealth"; dur: number };
  /** ally save (see SaveKit) */
  save?: SaveKit;
  /** buff on allies around the caster or on one ally */
  allyBuff?: AllyBuffKit;
  /** the CC only applies when the target is already in this state: airborne (Yasuo R), mark (Brand Q ablaze,
   *  Ryze W flux, Vex fear with Gloom, Taliyah E after W), or the caster's own setup */
  requires?: "airborne" | "mark";
}

/** How the champion plays in a teamfight. */
export type FightRole = "frontline" | "diver" | "assassin" | "skirmisher" | "backline" | "artillery" | "enchanter";

export interface ChampionKit {
  id: string;
  role: FightRole;
  spells: SpellKit[];
  /**
   * Share of the champion's damage to champions that came from [basic attacks, Q, W, E, R] in 2026 LCK kills
   * (from victimDamageReceived in the 502 timelines). Undefined when the champion has too few games.
   */
  dmgShare?: [number, number, number, number, number];
  /** how many pro games the numbers above come from */
  games?: number;
}
